query AddrEvents($resolverIds: [String!]!) {
  addrChangeds(
    where: { resolver_in: $resolverIds }
    orderBy: blockNumber
    orderDirection: desc
    first: 1000
  ) {
    id
    blockNumber
    resolver { id address }
    addr { id }
  }
  multicoinAddrChangeds(
    where: { coinType: 60, resolver_in: $resolverIds }
    orderBy: blockNumber
    orderDirection: desc
    first: 1000
  ) {
    id
    blockNumber
    resolver { id address }
    addr
  }
  versionChangeds(
    where: { resolver_in: $resolverIds }
    orderBy: blockNumber
    orderDirection: desc
    first: 1000
  ) {
    id
    blockNumber
    resolver { id address }
  }
}
